"""Synthetic match engine: events first, then tracking that is consistent with them.

The engine is fully deterministic for a given (seed, params). It produces:

* an ordered list of :class:`MatchEvent` (passes, carries, pressures, tackles,
  interceptions, shots, saves, fouls, cards, substitutions, restarts),
* ball waypoints, and
* 10 Hz tracking for all 22 players plus the ball, generated by steering each
  player towards a context-dependent target (team shape, ball carrier, pass
  receiver, presser, attacking runs) under speed and acceleration limits.
"""

from __future__ import annotations

import math
import random
from collections.abc import Iterator
from dataclasses import dataclass, field

import numpy as np

from matchlens.contracts import (
    HALF_LENGTH,
    HALF_WIDTH,
    Frame,
    MatchEvent,
    MatchMetadata,
    PlayerPos,
    StreamMessage,
    Team,
    TrackingBatch,
)
from matchlens.sim.params import load_params, params_version
from matchlens.world import FORMATIONS, make_fixture

TEAMS = ("h", "a")
SIGN = {"h": 1.0, "a": -1.0}


def other(team: str) -> str:
    return "a" if team == "h" else "h"


def to_abs(team: str, xa: float, ya: float) -> tuple[float, float]:
    s = SIGN[team]
    return s * xa, s * ya


def to_att(team: str, x: float, y: float) -> tuple[float, float]:
    s = SIGN[team]
    return s * x, s * y


def clamp_pitch(x: float, y: float) -> tuple[float, float]:
    return max(-HALF_LENGTH, min(HALF_LENGTH, x)), max(-HALF_WIDTH, min(HALF_WIDTH, y))


def sigmoid(z: float) -> float:
    return 1.0 / (1.0 + math.exp(-z))


def shot_geometry(xa: float, ya: float) -> tuple[float, float]:
    """Distance to goal centre and the angle subtended by the goal mouth (radians)."""
    dx = HALF_LENGTH - xa
    dist = math.hypot(dx, ya)
    half_goal = 3.66
    a1 = math.atan2(ya + half_goal, dx)
    a2 = math.atan2(ya - half_goal, dx)
    return dist, abs(a1 - a2)


def display_clock(clock_s: float, period: int, period_start_s: float, period_min: float = 45) -> str:
    regulation = period_min * 60
    base = 0 if period == 1 else regulation
    elapsed = clock_s - period_start_s
    if elapsed <= regulation:
        total = base + elapsed
        return f"{int(total // 60):02d}:{int(total % 60):02d}"
    extra = elapsed - regulation
    return f"{int((base + regulation) // 60)}+{int(extra // 60) + 1}:{int(extra % 60):02d}"


@dataclass
class Waypoint:
    t: float
    x: float
    y: float
    z: float = 0.0


@dataclass
class Segment:
    """Who has the ball and who is doing what between t0 and t1 (drives tracking targets)."""

    t0: float
    t1: float
    team: str
    carrier: str | None = None
    receiver: str | None = None
    receiver_target: tuple[float, float] | None = None
    presser: str | None = None


@dataclass
class SimResult:
    metadata: MatchMetadata
    events: list[MatchEvent]
    tracking_t: np.ndarray  # (T,)
    tracking_ball: np.ndarray  # (T, 3)
    tracking_players: np.ndarray  # (T, P, 2), NaN when off the pitch
    player_ids: list[str]
    period_bounds: list[tuple[float, float]]

    def stream(self, batch_s: float = 1.0) -> Iterator[StreamMessage]:
        """Merge events and 1 s tracking batches in clock order."""
        mid = self.metadata.match_id
        yield StreamMessage(kind="metadata", match_id=mid, clock_s=0.0, payload=self.metadata.model_dump(mode="json"))
        ev_i = 0
        n_ev = len(self.events)
        fps = self.metadata.fps
        frames_per_batch = max(1, int(round(batch_s * fps)))
        T = len(self.tracking_t)
        for start in range(0, T, frames_per_batch):
            end = min(T, start + frames_per_batch)
            t_end = float(self.tracking_t[end - 1])
            while ev_i < n_ev and self.events[ev_i].clock_s <= t_end:
                e = self.events[ev_i]
                yield StreamMessage(kind="event", match_id=mid, clock_s=e.clock_s, payload=e.model_dump(mode="json"))
                ev_i += 1
            frames = []
            for k in range(start, end):
                players = [
                    PlayerPos(id=pid, x=round(float(p[0]), 2), y=round(float(p[1]), 2))
                    for pid, p in zip(self.player_ids, self.tracking_players[k], strict=True)
                    if not math.isnan(p[0])
                ]
                b = self.tracking_ball[k]
                frames.append(
                    Frame(
                        t_s=round(float(self.tracking_t[k]), 2),
                        ball=(round(float(b[0]), 2), round(float(b[1]), 2), round(float(b[2]), 2)),
                        players=players,
                    )
                )
            period = 1 if float(self.tracking_t[start]) < self.period_bounds[0][1] + 1e-6 else 2
            batch = TrackingBatch(match_id=mid, period=period, t0_s=float(self.tracking_t[start]), fps=fps, frames=frames)
            yield StreamMessage(kind="tracking", match_id=mid, clock_s=batch.t0_s, payload=batch.model_dump(mode="json"))
        while ev_i < n_ev:
            e = self.events[ev_i]
            yield StreamMessage(kind="event", match_id=mid, clock_s=e.clock_s, payload=e.model_dump(mode="json"))
            ev_i += 1
        last = self.events[-1].clock_s if self.events else 0.0
        yield StreamMessage(kind="end", match_id=mid, clock_s=last, payload={"match_id": mid})


@dataclass
class _TeamState:
    team: Team
    on_pitch: list[str]  # slot index -> player id
    slot_pos: list[str]
    anchors: list[tuple[float, float]]
    strength: float
    subs_left: list[tuple[float, int, str]] = field(default_factory=list)  # (time, slot, incoming id)


class MatchEngine:
    def __init__(self, seed: int, match_id: str | None = None, params: dict | None = None, fps: int = 10):
        self.seed = seed
        self.rng = random.Random(seed)
        self.p = load_params(params)
        self.fps = fps
        self.match_id = match_id or f"m{seed:05d}"
        home, away = make_fixture(seed)
        self.teams = {"h": home, "a": away}
        self.ts: dict[str, _TeamState] = {}
        for tid, team in self.teams.items():
            form = FORMATIONS[team.formation]
            self.ts[tid] = _TeamState(
                team=team,
                on_pitch=[pl.id for pl in team.players[:11]],
                slot_pos=[pos for pos, _, _ in form],
                anchors=[(ax, ay) for _, ax, ay in form],
                strength=1.0 + self.rng.gauss(0, self.p["strength_sd"]),
            )
        self.player_team = {pl.id: tid for tid, t in self.teams.items() for pl in t.players}
        self.max_speed = {
            pl.id: self.rng.uniform(*self.p["max_speed_mps"]) * (0.85 if pl.position == "GK" else 1.0)
            for t in self.teams.values()
            for pl in t.players
        }
        self.events: list[MatchEvent] = []
        self.waypoints: list[Waypoint] = []
        self.segments: list[Segment] = []
        self.seq = 0
        self.period = 1
        self.period_start = 0.0
        self.period_bounds: list[tuple[float, float]] = []

    # ------------------------------------------------------------------ helpers
    def _emit(self, t: float, etype: str, team: str | None = None, player: str | None = None, **kw) -> MatchEvent:
        self.seq += 1
        ev = MatchEvent(
            event_id=f"{self.match_id}-e{self.seq:05d}",
            match_id=self.match_id,
            seq=self.seq,
            period=self.period,
            clock_s=round(t, 2),
            display_clock=display_clock(t, self.period, self.period_start, self.p["period_min"]),
            type=etype,  # type: ignore[arg-type]
            team_id=team,
            player_id=player,
            **kw,
        )
        self.events.append(ev)
        return ev

    def _script(self, t: float, team: str) -> dict[str, float]:
        minute = self._minute(t)
        out = {"press": 0.0, "tempo": 0.0}
        for s in self.p["script"]:
            if s["team"] == team and s["from_min"] <= minute < s["to_min"]:
                out["press"] += s.get("press", 0.0)
                out["tempo"] += s.get("tempo", 0.0)
        return out

    def _minute(self, t: float) -> float:
        """Minute on a 90-minute scale, so scripted stories fire at the same phase in short matches."""
        frac = (t - self.period_start) / (self.p["period_min"] * 60)
        return 45 * frac + (0 if self.period == 1 else 45)

    def shape(self, team: str, ball_xa: float, ball_ya: float, in_possession: bool) -> list[tuple[float, float]]:
        """Target positions (team-attacking frame) of the 11 slots given the ball."""
        st = self.ts[team]
        push = 9.0 if in_possession else -4.0
        shift_x = 0.42 * ball_xa + push
        out = []
        for (ax, ay), pos in zip(st.anchors, st.slot_pos, strict=True):
            if pos == "GK":
                out.append((-49.0 + max(0.0, (ball_xa + 20) * 0.08), ball_ya * 0.12))
                continue
            x = ax + shift_x
            y = ay * (0.85 if not in_possession else 1.05) + ball_ya * 0.3
            x = min(x, 44.0 if in_possession else 30.0)
            x = max(x, -46.0)
            out.append((x, max(-HALF_WIDTH + 1.5, min(HALF_WIDTH - 1.5, y))))
        return out

    def _slot_of(self, team: str, pid: str) -> int:
        return self.ts[team].on_pitch.index(pid)

    def _nearest(self, team: str, xa_other: float, ya_other: float, other_team: str, exclude_gk: bool = True) -> str:
        """Nearest player of `team` (by shape anchor) to a point given in `other_team`'s attacking frame."""
        x_abs, y_abs = to_abs(other_team, xa_other, ya_other)
        bx, by = to_att(team, x_abs, y_abs)
        targets = self.shape(team, bx, by, in_possession=False)
        best, best_d = None, 1e9
        for slot, (tx, ty) in enumerate(targets):
            if exclude_gk and self.ts[team].slot_pos[slot] == "GK":
                continue
            d = math.hypot(tx - bx, ty - by)
            if d < best_d:
                best, best_d = slot, d
        return self.ts[team].on_pitch[best]  # type: ignore[index]

    def _gk(self, team: str) -> str:
        return self.ts[team].on_pitch[0]

    def _ball(self, t: float, team: str, xa: float, ya: float, z: float = 0.0) -> None:
        x, y = to_abs(team, xa, ya)
        x, y = clamp_pitch(x, y)
        self.waypoints.append(Waypoint(t, x, y, z))

    # ------------------------------------------------------------------ events
    def simulate_events(self) -> None:
        p, rng = self.p, self.rng
        t = 0.0
        first_kickoff = "h" if rng.random() < 0.5 else "a"
        for period in (1, 2):
            self.period = period
            self.period_start = t
            stoppage = rng.uniform(*p["stoppage_s"]) * (0.6 if period == 1 else 1.0) * p["period_min"] / 45
            end_t = t + p["period_min"] * 60 + stoppage
            self._emit(t, "period_start", qualifiers={"period": period})
            team = first_kickoff if period == 1 else other(first_kickoff)
            self._schedule_subs(period, t)
            t, team = self._kickoff(t, team, delay=0.0)
            carrier = self._kickoff_taker
            xa, ya = 0.0, 0.0
            while t < end_t:
                t = self._apply_subs(t, team)
                if carrier not in self.ts[team].on_pitch:
                    carrier = self.ts[team].on_pitch[5]
                t, team, carrier, xa, ya = self._action(t, team, carrier, xa, ya)
            self._emit(t, "period_end", qualifiers={"period": period})
            self.period_bounds.append((self.period_start, t))
            self.segments.append(Segment(t, t + 0.01, team))

    _kickoff_taker: str = ""

    def _kickoff(self, t: float, team: str, delay: float) -> tuple[float, str]:
        t += delay
        self._kickoff_taker = self.ts[team].on_pitch[-1]
        self._ball(t, team, 0.0, 0.0)
        return t, team

    def _schedule_subs(self, period: int, t0: float) -> None:
        if period != 2:
            return
        for tid in TEAMS:
            st = self.ts[tid]
            bench = [pl for pl in st.team.players[11:]]
            self.rng.shuffle(bench)
            subs = []
            for i in range(3):
                when = t0 + self.rng.uniform(12, 40) * 60 * self.p["period_min"] / 45
                outfield_slots = [s for s in range(1, 11)]
                slot = self.rng.choice(outfield_slots)
                subs.append((when, slot, bench[i].id))
            st.subs_left = sorted(subs)

    def _apply_subs(self, t: float, team_in_poss: str) -> float:
        for tid in TEAMS:
            st = self.ts[tid]
            while st.subs_left and st.subs_left[0][0] <= t:
                _, slot, incoming = st.subs_left.pop(0)
                if incoming in st.on_pitch:
                    continue
                outgoing = st.on_pitch[slot]
                self._emit(t, "substitution", tid, outgoing, related_player_id=incoming)
                st.on_pitch[slot] = incoming
                t += self.rng.uniform(*self.p["restart_s"]["sub"])
        return t

    def _action(self, t: float, team: str, carrier: str, xa: float, ya: float):
        p, rng = self.p, self.rng
        opp = other(team)
        st = self.ts[team]
        script_opp = self._script(t, opp)
        script_own = self._script(t, team)
        tempo = 1.0 + script_own["tempo"]
        t += rng.uniform(*p["reaction_s"]) / tempo

        # Pressure on the carrier
        high_zone = xa < -10.0  # carrier in own half: a high press is happening
        p_press = p["pressure_base"] + (p["pressure_high_zone_bonus"] if high_zone else 0.0) + 0.3 * script_opp["press"]
        presser = None
        if rng.random() < min(0.85, p_press):
            presser = self._nearest(opp, xa, ya, team)
            self._emit(t, "pressure", opp, presser, x=to_abs(team, xa, ya)[0], y=to_abs(team, xa, ya)[1])
        pressured = presser is not None

        dist, angle = shot_geometry(xa, ya)
        p_shot = 0.0
        if dist < p["shot_max_dist_m"] and xa > 15:
            p_shot = sigmoid(p["shot_logit_intercept"] + p["shot_logit_per_m"] * dist + 0.8 * angle) * st.strength
        r = rng.random()
        if r < p_shot:
            return self._shot(t, team, carrier, xa, ya, pressured)
        if r < p_shot + p["carry_prob"] * (1 - p_shot):
            return self._carry(t, team, carrier, xa, ya, presser)
        if presser and rng.random() < p["tackle_attempt_on_pressured_pass"]:
            return self._duel(t, team, carrier, xa, ya, presser)
        return self._pass(t, team, carrier, xa, ya, presser)

    def _duel(self, t, team, carrier, xa, ya, presser):
        """A pressing defender challenges before the pass: tackle won, or a foul."""
        p, rng = self.p, self.rng
        opp = other(team)
        x, y = to_abs(team, xa, ya)
        self.segments.append(Segment(t, t + 0.8, team, carrier=carrier, presser=presser))
        if rng.random() < p["foul_share_of_tackles"]:
            self._emit(t + 0.8, "foul", opp, presser, x=x, y=y, related_player_id=carrier)
            if rng.random() < p["card_share_of_fouls"]:
                self._emit(t + 1.8, "card", opp, presser, outcome="yellow")
            restart = rng.uniform(*p["restart_s"]["free_kick"])
            self.segments.append(Segment(t + 0.8, t + 0.8 + restart, team, carrier=carrier))
            return t + 0.8 + restart, team, carrier, xa, ya
        self._emit(t + 0.8, "tackle", opp, presser, x=x, y=y, outcome="won", related_player_id=carrier)
        oxa, oya = to_att(opp, x, y)
        return t + 0.8, opp, presser, oxa, oya

    def _pass(self, t, team, carrier, xa, ya, presser):
        p, rng = self.p, self.rng
        opp = other(team)
        st = self.ts[team]
        targets = self.shape(team, xa, ya, in_possession=True)
        cands, weights = [], []
        for slot, (tx, ty) in enumerate(targets):
            pid = st.on_pitch[slot]
            if pid == carrier:
                continue
            d = math.hypot(tx - xa, ty - ya)
            if d < 4:
                continue
            fwd = tx - xa
            w = math.exp(-(((d - p["pass_target_len_m"]) / p["pass_len_spread_m"]) ** 2)) * (1.0 + 0.5 * max(-0.5, fwd / 20))
            if st.slot_pos[slot] == "GK":
                w *= 0.15 if xa < -15 else 0.01
            cands.append((pid, tx + rng.gauss(0, 2.5), ty + rng.gauss(0, 2.5)))
            weights.append(max(w, 1e-4))
        receiver, ex, ey = rng.choices(cands, weights=weights)[0]
        ex, ey = clamp_pitch(ex, ey)
        length = math.hypot(ex - xa, ey - ya)
        fwd = max(0.0, ex - xa)
        p_ok = (
            p["pass_base"]
            - p["pass_len_penalty_per_m"] * length
            - p["pass_forward_penalty"] * (fwd / 20)
            - (p["pass_pressure_penalty"] if presser else 0.0)
        ) * st.strength
        if ex > 30:
            p_ok -= 0.08  # into the box is harder
        p_ok = max(0.25, min(0.98, p_ok))
        speed = rng.uniform(*p["ball_speed_mps"])
        dur = max(0.4, length / speed)
        x0, y0 = to_abs(team, xa, ya)
        z = min(6.0, 0.12 * max(0.0, length - 25)) if length > 25 else 0.0
        if rng.random() < p_ok:
            x1, y1 = to_abs(team, ex, ey)
            self._emit(
                t, "pass", team, carrier, x=x0, y=y0, end_x=x1, end_y=y1, outcome="complete",
                related_player_id=receiver,
                qualifiers={"length_m": round(length, 1), "under_pressure": presser is not None,
                            "difficulty": round(1 - p_ok, 3), "ball_speed_mps": round(speed, 1),
                            "progressive_m": round(fwd, 1)},
            )
            self.segments.append(Segment(t, t + dur, team, carrier=None, receiver=receiver, receiver_target=(ex, ey), presser=presser))
            self._ball(t, team, xa, ya)
            if z:
                self._ball(t + dur / 2, team, (xa + ex) / 2, (ya + ey) / 2, z)
            self._ball(t + dur, team, ex, ey)
            return t + dur, team, receiver, ex, ey
        # Failed pass
        frac = rng.uniform(0.55, 0.95)
        ix, iy = xa + (ex - xa) * frac, ya + (ey - ya) * frac
        x1, y1 = to_abs(team, ex, ey)
        out = rng.random() < p["ball_out_share_of_failed_passes"]
        self._emit(
            t, "pass", team, carrier, x=x0, y=y0, end_x=x1, end_y=y1, outcome="out" if out else "intercepted",
            related_player_id=receiver,
            qualifiers={"length_m": round(length, 1), "under_pressure": presser is not None,
                        "difficulty": round(1 - p_ok, 3), "ball_speed_mps": round(speed, 1),
                        "progressive_m": round(fwd, 1)},
        )
        self._ball(t, team, xa, ya)
        if out:
            oy = math.copysign(HALF_WIDTH, iy if iy != 0 else 1.0)
            self._ball(t + dur, team, ix, oy)
            self._emit(t + dur, "ball_out", team, None, x=to_abs(team, ix, oy)[0], y=to_abs(team, ix, oy)[1], qualifiers={"restart": "throw_in"})
            self.segments.append(Segment(t, t + dur, team, receiver=receiver, receiver_target=(ex, ey), presser=presser))
            restart = rng.uniform(*p["restart_s"]["throw_in"])
            oxa, oya = to_att(opp, *to_abs(team, ix, oy))
            taker = self._nearest(opp, ix, oy, team)
            self.segments.append(Segment(t + dur, t + dur + restart, opp, carrier=taker))
            self._ball(t + dur + restart, opp, oxa, oya)
            return t + dur + restart, opp, taker, oxa, oya
        interceptor = self._nearest(opp, ix, iy, team)
        ixa, iya = to_att(opp, *to_abs(team, ix, iy))
        idur = dur * frac
        kind = "interception" if rng.random() < p["interception_share_of_failed_passes"] else "recovery"
        self._emit(t + idur, kind, opp, interceptor, x=to_abs(team, ix, iy)[0], y=to_abs(team, ix, iy)[1])
        self.segments.append(Segment(t, t + idur, team, receiver=receiver, receiver_target=(ex, ey), presser=interceptor))
        self._ball(t + idur, team, ix, iy)
        return t + idur, opp, interceptor, ixa, iya

    def _carry(self, t, team, carrier, xa, ya, presser):
        p, rng = self.p, self.rng
        opp = other(team)
        dist = rng.uniform(3, 13)
        ang = rng.gauss(0, 0.6)
        ex, ey = clamp_pitch(xa + dist * math.cos(ang), ya + dist * math.sin(ang))
        ex = min(ex, HALF_LENGTH - 2)
        speed = rng.uniform(3.5, 6.5)
        dur = max(0.5, math.hypot(ex - xa, ey - ya) / speed)
        x0, y0 = to_abs(team, xa, ya)
        if presser and rng.random() < p["carry_loss_under_pressure"]:
            lose = dur * rng.uniform(0.3, 0.8)
            lx, ly = xa + (ex - xa) * lose / dur, ya + (ey - ya) * lose / dur
            lxa, lya = to_att(opp, *to_abs(team, lx, ly))
            self.segments.append(Segment(t, t + lose, team, carrier=carrier, presser=presser))
            self._ball(t, team, xa, ya)
            self._ball(t + lose, team, lx, ly)
            if rng.random() < p["foul_share_of_tackles"]:
                self._emit(t + lose, "foul", opp, presser, x=to_abs(team, lx, ly)[0], y=to_abs(team, lx, ly)[1], related_player_id=carrier)
                if rng.random() < p["card_share_of_fouls"]:
                    self._emit(t + lose + 1, "card", opp, presser, outcome="yellow")
                restart = rng.uniform(*p["restart_s"]["free_kick"])
                self.segments.append(Segment(t + lose, t + lose + restart, team, carrier=carrier))
                return t + lose + restart, team, carrier, lx, ly
            self._emit(t + lose, "tackle", opp, presser, x=to_abs(team, lx, ly)[0], y=to_abs(team, lx, ly)[1], outcome="won", related_player_id=carrier)
            return t + lose, opp, presser, lxa, lya
        x1, y1 = to_abs(team, ex, ey)
        self._emit(t, "carry", team, carrier, x=x0, y=y0, end_x=x1, end_y=y1,
                   qualifiers={"length_m": round(math.hypot(ex - xa, ey - ya), 1), "progressive_m": round(max(0.0, ex - xa), 1)})
        self.segments.append(Segment(t, t + dur, team, carrier=carrier, presser=presser))
        self._ball(t, team, xa, ya)
        self._ball(t + dur, team, ex, ey)
        return t + dur, team, carrier, ex, ey

    def _shot(self, t, team, carrier, xa, ya, pressured):
        p, rng = self.p, self.rng
        opp = other(team)
        dist, angle = shot_geometry(xa, ya)
        xg = sigmoid(p["xg_a"] + p["xg_b"] * dist + p["xg_c"] * angle) * (0.8 if pressured else 1.0)
        xg = round(min(0.95, xg), 3)
        speed_kmh = round(min(125.0, rng.uniform(55, 80) + dist * rng.uniform(0.8, 1.6)), 1)
        x0, y0 = to_abs(team, xa, ya)
        gy = rng.uniform(-3.4, 3.4)
        gx_abs, gy_abs = to_abs(team, HALF_LENGTH, gy)
        dur = max(0.3, dist / (speed_kmh / 3.6))
        goal = rng.random() < xg
        if goal:
            outcome = "goal"
        else:
            split = p["shot_outcome_split"]
            outcome = rng.choices(list(split), weights=list(split.values()))[0]
        self._emit(t, "shot", team, carrier, x=x0, y=y0, end_x=gx_abs, end_y=gy_abs, outcome=outcome,
                   qualifiers={"xg": xg, "distance_m": round(dist, 1), "angle_rad": round(angle, 3),
                               "shot_speed_kmh": speed_kmh, "under_pressure": pressured,
                               "body_part": rng.choice(["right_foot", "right_foot", "left_foot", "head"])})
        self.segments.append(Segment(t, t + dur, team, carrier=None))
        self._ball(t, team, xa, ya)
        if goal:
            self._ball(t + dur, team, HALF_LENGTH + 0.5, gy, 0.8)
            restart = rng.uniform(*p["restart_s"]["kickoff"])
            self.segments.append(Segment(t + dur, t + dur + restart, opp))
            t2, _ = self._kickoff(t + dur + restart, opp, 0.0)
            return t2, opp, self._kickoff_taker, 0.0, 0.0
        gk = self._gk(opp)
        if outcome == "saved":
            self._ball(t + dur, team, HALF_LENGTH - 1.0, gy * 0.6, 0.5)
            self._emit(t + dur, "save", opp, gk, x=to_abs(team, HALF_LENGTH - 1.0, gy * 0.6)[0], y=to_abs(team, HALF_LENGTH - 1.0, gy * 0.6)[1])
            if rng.random() < p["corner_after_save"]:
                return self._corner(t + dur, team)
            gxa = -HALF_LENGTH + 1.0
            self.segments.append(Segment(t + dur, t + dur + 6, opp, carrier=gk))
            return t + dur + rng.uniform(4, 9), opp, gk, gxa, 0.0
        if outcome == "blocked" and rng.random() < p["corner_after_block"]:
            self._ball(t + dur * 0.4, team, xa + (HALF_LENGTH - xa) * 0.3, ya)
            return self._corner(t + dur, team)
        # Off target or blocked out -> goal kick
        self._ball(t + dur, team, HALF_LENGTH + 2, gy * 2.5)
        restart = rng.uniform(*p["restart_s"]["goal_kick"])
        self.segments.append(Segment(t + dur, t + dur + restart, opp, carrier=gk))
        self._ball(t + dur + restart, opp, -HALF_LENGTH + 5.5, 0.0)
        return t + dur + restart, opp, gk, -HALF_LENGTH + 5.5, 0.0

    def _corner(self, t, team):
        rng = self.rng
        restart = rng.uniform(*self.p["restart_s"]["corner"])
        side = rng.choice([-1.0, 1.0])
        cx, cy = HALF_LENGTH - 0.5, side * (HALF_WIDTH - 0.5)
        taker = self.ts[team].on_pitch[8]
        self.segments.append(Segment(t, t + restart, team, carrier=taker))
        self._ball(t + restart, team, cx, cy)
        return t + restart, team, taker, cx, cy

    # ------------------------------------------------------------------ tracking
    def simulate_tracking(self) -> tuple[np.ndarray, np.ndarray, np.ndarray, list[str]]:
        p, rng = self.p, np.random.default_rng(self.seed)
        dt = 1.0 / self.fps
        t_end = self.period_bounds[-1][1]
        T = int(t_end * self.fps) + 1
        ts = np.arange(T) * dt

        # Ball: piecewise-linear interpolation through waypoints
        wps = sorted(self.waypoints, key=lambda w: w.t)
        wt = np.array([w.t for w in wps])
        ball = np.zeros((T, 3))
        ball[:, 0] = np.interp(ts, wt, [w.x for w in wps])
        ball[:, 1] = np.interp(ts, wt, [w.y for w in wps])
        ball[:, 2] = np.interp(ts, wt, [w.z for w in wps])

        all_ids = [pl.id for tid in TEAMS for pl in self.teams[tid].players]
        idx = {pid: i for i, pid in enumerate(all_ids)}
        P = len(all_ids)
        pos = np.full((P, 2), np.nan)
        vel = np.zeros((P, 2))
        out = np.full((T, P, 2), np.nan, dtype=np.float32)
        vmax = np.array([self.max_speed[pid] for pid in all_ids])

        # Rebuild on-pitch slots over time from substitution events
        lineup = {tid: [pl.id for pl in self.teams[tid].players[:11]] for tid in TEAMS}
        subs = [e for e in self.events if e.type == "substitution"]
        sub_i = 0
        segs = sorted(self.segments, key=lambda s: s.t0)
        seg_i = 0
        cur = segs[0]
        runs: dict[str, float] = {}
        drift = np.zeros((P, 2))
        tau = max(0.5, float(p.get("drift_tau_s", 8.0)))
        drift_sd = float(p.get("drift_m", 0.0)) * math.sqrt(2 * dt / tau)

        for k in range(T):
            t = ts[k]
            while sub_i < len(subs) and subs[sub_i].clock_s <= t:
                e = subs[sub_i]
                slot = lineup[e.team_id].index(e.player_id)
                lineup[e.team_id][slot] = e.related_player_id
                old = idx[e.player_id]
                new = idx[e.related_player_id]
                pos[new] = pos[old]  # the substitute takes over at the same spot
                pos[old] = np.nan
                vel[old] = 0
                sub_i += 1
            while seg_i + 1 < len(segs) and segs[seg_i + 1].t0 <= t:
                seg_i += 1
                cur = segs[seg_i]
            bx, by = ball[k, 0], ball[k, 1]
            if drift_sd:
                drift += -drift * (dt / tau) + rng.normal(0, drift_sd, (P, 2))
            for tid in TEAMS:
                in_poss = cur.team == tid
                bxa, bya = to_att(tid, bx, by)
                targets = self.shape(tid, bxa, bya, in_possession=in_poss)
                for slot, pid in enumerate(lineup[tid]):
                    i = idx[pid]
                    tx, ty = targets[slot]
                    if in_poss and self.ts[tid].slot_pos[slot] in ("ST", "RW", "LW", "RM", "LM", "CM") and bxa > -10:
                        if pid in runs and runs[pid] > t:
                            tx = min(44.0, tx + 14.0)
                        elif rng.random() < p["run_prob_per_s"] * dt:
                            runs[pid] = t + rng.uniform(2.0, 4.5)
                    tgt = np.array(to_abs(tid, tx, ty)) + drift[i]
                    urgent = pid in runs and runs[pid] > t  # attacking run: full speed
                    if pid == cur.carrier:
                        tgt = np.array([bx, by]) - np.array([SIGN[tid] * 0.6, 0.0])
                    elif pid == cur.receiver and cur.receiver_target is not None:
                        tgt = np.array(to_abs(tid, *cur.receiver_target))
                    elif pid == cur.presser:
                        tgt = np.array([bx, by]) + np.array([SIGN[tid] * 1.2, 0.0])
                        urgent = True
                    if np.isnan(pos[i][0]):
                        pos[i] = tgt
                    gap = tgt - pos[i]
                    gap_d = float(np.linalg.norm(gap))
                    if urgent and gap_d > p.get("urgent_min_gap_m", 8.0):
                        desired = gap / gap_d * vmax[i]  # sprint
                    else:
                        desired = gap * p["steer_gain"]
                        sp = np.linalg.norm(desired)
                        if sp > p.get("jog_max_mps", 5.5):  # non-urgent movement tops out at a run
                            desired *= p.get("jog_max_mps", 5.5) / sp
                    dv = desired - vel[i]
                    a = np.linalg.norm(dv)
                    amax = p["max_accel_mps2"] * dt
                    if a > amax:
                        dv *= amax / a
                    vel[i] += dv + rng.normal(0, 0.012, 2)
                    pos[i] += vel[i] * dt
                    pos[i][0] = min(HALF_LENGTH + 2, max(-HALF_LENGTH - 2, pos[i][0]))
                    pos[i][1] = min(HALF_WIDTH + 2, max(-HALF_WIDTH - 2, pos[i][1]))
            out[k] = pos
        return ts, ball, out, all_ids

    # ------------------------------------------------------------------ public
    def run(self) -> SimResult:
        self.simulate_events()
        ts, ball, players, ids = self.simulate_tracking()
        meta = MatchMetadata(
            match_id=self.match_id,
            home=self.teams["h"],
            away=self.teams["a"],
            seed=self.seed,
            params_version=params_version(self.p),
            fps=self.fps,
            period_min=float(self.p["period_min"]),
        )
        return SimResult(meta, self.events, ts, ball, players, ids, self.period_bounds)


def simulate(seed: int, match_id: str | None = None, params: dict | None = None, fps: int = 10) -> SimResult:
    return MatchEngine(seed, match_id=match_id, params=params, fps=fps).run()
